/* 2026-08-21 final usability and sales-conversion polish */
(function(){
function contactHref(type){const a=document.querySelector(type==='phone'?'a[href^="tel:"]':'a[href*="qr.kakao.com"]');return a?a.getAttribute('href'):'#contact'}
function ctaHTML(title,sub){return '<div class="final-model-cta"><div class="final-cta-copy"><b>'+title+'</b><small>'+sub+'</small></div><div class="final-cta-actions"><a href="'+contactHref('phone')+'">전화 상담</a><a class="kakao" href="'+contactHref('kakao')+'">카카오톡 상담</a></div></div>'}
function appendModelCta(key){const body=document.getElementById('mbody');if(!body||body.querySelector('.final-model-cta'))return;const n=(typeof names!=='undefined'&&names[key])?names[key]:key;body.insertAdjacentHTML('beforeend',ctaHTML(n+' 견적·시승 상담','트림 선택이 애매하면 예산과 주행 환경을 기준으로 필요한 차이만 함께 비교해드립니다.'))}
function appendGenericCta(){const body=document.getElementById('mbody');if(!body||body.querySelector('.final-model-cta'))return;body.insertAdjacentHTML('beforeend',ctaHTML('트림 선택 상담','가격표만으로 결정하기 어렵다면 실제 필요한 사양을 기준으로 빠르게 좁혀드립니다.'))}
function patchDark(key){const price=document.querySelector('#mbody .dg-price');const note=document.querySelector('#mbody .dg-copy p');if(key==='XC60'){if(price)price.textContent='7,070만 원 · Air Sus 7,330만 원';if(note)note.textContent='XC60 Dark는 외장 액센트를 고광택 블랙으로 바꾸는 테마입니다. 20인치 휠은 Bright/Dark 공통 Ultra 구성이며, 에어 서스펜션은 선택 사양으로 적용 시 7,330만 원입니다.'}else if(key==='S90'){if(price)price.textContent='7,130만 원 · Air Sus 7,390만 원';if(note)note.textContent='S90 Dark는 Ultra의 주요 편의·시트·오디오 사양을 유지하면서 그릴, 사이드미러, 윈도우 데코를 블랙 계열로 바꾸는 테마입니다. 20인치 휠은 Dark 전용이 아니며, 에어 서스펜션은 선택 사양입니다.'}}
function wrapFunctions(){if(window.__finalUxWrapped)return;if(typeof window.openModel==='function'){const old=window.openModel;window.openModel=function(key){old(key);requestAnimationFrame(function(){appendModelCta(key)})}}if(typeof window.openAllTrims==='function'){const old=window.openAllTrims;window.openAllTrims=function(){old();requestAnimationFrame(appendGenericCta)}}if(typeof window.openDarkGuide==='function'){const old=window.openDarkGuide;window.openDarkGuide=function(key){key=key||'XC40';old(key);requestAnimationFrame(function(){patchDark(key)})}}if(typeof window.renderDarkGuide==='function'){const old=window.renderDarkGuide;window.renderDarkGuide=function(key){old(key);requestAnimationFrame(function(){patchDark(key)})}}window.__finalUxWrapped=true}
function installQuickNav(){const hamb=document.querySelector('.hamb');if(!hamb||document.querySelector('.mobile-quick-nav'))return;const mp=document.querySelector('.mobile-profile');if(mp&&!mp.id)mp.id='mobile-contact';hamb.removeAttribute('onclick');hamb.setAttribute('aria-label','빠른 메뉴 열기');hamb.setAttribute('aria-expanded','false');const menu=document.createElement('div');menu.className='mobile-quick-nav';menu.setAttribute('aria-hidden','true');menu.innerHTML='<a href="#lineup">모델 라인업</a><button type="button" data-open-trims>트림·가격</button><a href="#dark-guide">Dark 테마</a><a href="#colors">컬러</a><a href="#service">서비스센터</a><a href="#mobile-contact">상담</a>';const top=document.querySelector('.top');if(top&&top.parentNode)top.parentNode.insertBefore(menu,top.nextSibling);function open(v){menu.classList.toggle('open',v);menu.setAttribute('aria-hidden',v?'false':'true');hamb.setAttribute('aria-expanded',v?'true':'false');hamb.textContent=v?'×':'☰'}hamb.addEventListener('click',function(e){e.stopPropagation();open(!menu.classList.contains('open'))});menu.addEventListener('click',function(e){if(e.target.closest('[data-open-trims]')){open(false);if(typeof window.openAllTrims==='function')window.openAllTrims();return}if(e.target.closest('a'))open(false)});document.addEventListener('click',function(e){if(menu.classList.contains('open')&&!menu.contains(e.target)&&e.target!==hamb)open(false)});window.addEventListener('resize',function(){if(innerWidth>1080)open(false)})}
function loadWarrantyGuide(){if(document.querySelector('script[data-warranty-guide-loader]'))return;const s=document.createElement('script');s.src='scripts/site-warranty-guide-20260821.js?v=20260821warranty1';s.setAttribute('data-warranty-guide-loader','1');document.body.appendChild(s)}
function harden(){const c=document.querySelector('.close');if(c)c.setAttribute('aria-label','상세 안내 닫기');document.documentElement.setAttribute('data-site-final-ux','20260821-2')}
function start(){wrapFunctions();installQuickNav();harden();loadWarrantyGuide()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
